let schemaReady = false, schemaPromise;
const id = () => crypto.randomUUID();
const json = v => v === undefined ? {} : v;
function hashPassword(password){ const salt=crypto.randomBytes(16).toString('hex'); return `${salt}:${crypto.scryptSync(password,salt,64).toString('hex')}`; }
function checkPassword(password, stored){ try { if(typeof stored==='string' && stored.startsWith('$2')) return bcrypt.compareSync(password,stored); const [salt,key]=stored.split(':'); return crypto.timingSafeEqual(crypto.scryptSync(password,salt,64),Buffer.from(key,'hex')); } catch { return false; } }
function token(payload){ const body=Buffer.from(JSON.stringify({...payload,exp:Date.now()+7*86400000})).toString('base64url'); return `${body}.${crypto.createHmac('sha256',secret).update(body).digest('base64url')}`; }
function readToken(raw){ try { const [body,sig]=raw.split('.'); const good=crypto.createHmac('sha256',secret).update(body).digest('base64url'); if(!sig||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(good))) return null; const p=JSON.parse(Buffer.from(body,'base64url')); return p.exp>Date.now()?p:null; } catch { return null; } }
async function ensureSchema(){ if(schemaReady) return; if(!schemaPromise) schemaPromise=(async()=>{ if(!databaseUrl) throw new Error('DATABASE_URL missing'); for(const statement of schema) await pool.query(statement); schemaReady=true; })().catch(e=>{schemaPromise=null; throw e}); return schemaPromise; }
async function q(text, params=[]){ await ensureSchema(); return pool.query({text,values:params}); }
async function auth(req,res,next){ const p=readToken((req.headers.authorization||'').replace(/^Bearer\s+/i,'')); if(!p?.uid||!p?.rid) return res.status(401).json({error:'unauthorized'}); try { const r=await q('SELECT id,restaurant_id,role FROM users WHERE id=$1 AND restaurant_id=$2 AND active=true',[p.uid,p.rid]); if(!r.rowCount) return res.status(401).json({error:'unauthorized'}); req.user={...p,uid:r.rows[0].id,rid:r.rows[0].restaurant_id,role:r.rows[0].role}; next(); } catch { res.status(503).json({error:'database_unavailable'}); } }
function bodyFields(body, allowed){ return allowed.map(k=>body[k]); }
const roles = (...allowed) => (req,res,next) => allowed.includes(req.user?.role) ? next() : res.status(403).json({error:'forbidden'});
const staff = roles('owner','admin','manager','cashier','staff');
const manager = roles('owner','admin','manager');
const courierOrStaff = roles('owner','admin','manager','cashier','staff','courier');
const cleanText=(v,max=300)=>typeof v==='string'?v.trim().slice(0,max):'';
const num=(v,min=0)=>Number.isFinite(Number(v))&&Number(v)>=min?Number(v):null;
const signedNum=(v,limit=1000000)=>Number.isFinite(Number(v))&&Math.abs(Number(v))<=limit?Number(v):null;
async function audit(req,action,entity,entityId,metadata={}){ try{await q('INSERT INTO audit_log(restaurant_id,actor_id,action,entity,entity_id,metadata) VALUES($1,$2,$3,$4,$5,$6)',[req.user.rid,req.user.uid,action,entity,entityId,metadata]);}catch(e){console.error('[audit]',e.message)} }

