// Staff accounts are created server-side so passwords are never exposed to Firebase/database writes.
app.post('/api/users',auth,manager,async(req,res)=>{
  const name=cleanText(req.body?.name,120), email=cleanText(req.body?.email,254).toLowerCase(), password=typeof req.body?.password==='string'?req.body.password:'', role=cleanText(req.body?.role,30);
  const allowed=['manager','cashier','kitchen','waiter','courier','staff'];
  if(!name||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<8||!allowed.includes(role)) return res.status(400).json({error:'invalid_user_payload'});
  if(role==='manager'&&req.user.role!=='owner') return res.status(403).json({error:'forbidden'});
  try {
    const hash=await bcrypt.hash(password,12);
    const r=await q('INSERT INTO users(id,restaurant_id,email,name,role,password_hash,active) VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id,name,email,role,active,created_at,last_access_at',[id(),req.user.rid,email,name,role,hash]);
    await audit(req,'create','user',r.rows[0].id,{role});
    res.status(201).json(r.rows[0]);
  } catch(e) { res.status(e?.code==='23505'?409:400).json({error:e?.code==='23505'?'email_exists':'invalid_data'}); }
});
app.patch('/api/users/:id',auth,manager,async(req,res)=>{const role=req.body?.role===undefined?undefined:cleanText(req.body.role,30),active=req.body?.active===undefined?undefined:req.body.active===true;if(role!==undefined&&!['owner','manager','cashier','kitchen','waiter','courier','staff'].includes(role))return res.status(400).json({error:'invalid_role'});if(role==='owner'&&req.user.role!=='owner')return res.status(403).json({error:'forbidden'});if(String(req.params.id)===String(req.user.uid)&&active===false)return res.status(400).json({error:'cannot_disable_self'});try{const r=await q(`UPDATE users SET role=COALESCE($1,role),active=COALESCE($2,active) WHERE id=$3 AND restaurant_id=$4 RETURNING id,name,email,role,active,created_at,last_access_at`,[role,active,req.params.id,req.user.rid]);if(!r.rowCount)return res.status(404).json({error:'not_found'});await audit(req,'update','user',req.params.id,{role,active});res.json(r.rows[0])}catch{res.status(400).json({error:'invalid_data'})}});
for(const [route,[table,fields]] of Object.entries(listRoutes)){ const guard=route==='reservations'?staff:manager; app.get('/api/'+route,auth,staff,async(req,res)=>{try{const r=await q(`SELECT * FROM ${table} WHERE restaurant_id=$1 ORDER BY ${(table === 'products' || table === 'inventory') ? 'updated_at' : 'created_at'} DESC NULLS LAST`,[req.user.rid]);res.json(r.rows)}catch{res.status(503).json({error:'database_unavailable'})}}); app.post('/api/'+route,auth,guard,async(req,res)=>{try{const vals=bodyFields(req.body||{},fields).map((v,i)=>['customer'].includes(fields[i])?json(v):v);if((table==='products'||table==='inventory'||table==='expenses')&&vals.some(v=>typeof v==='string'&&v.length>500))return res.status(400).json({error:'invalid_data'});const cols=['id','restaurant_id',...fields];const r=await q(`INSERT INTO ${table}(${cols.join(',')}) VALUES(${cols.map((_,i)=>'$'+(i+1)).join(',')}) RETURNING *`,[id(),req.user.rid,...vals]);await audit(req,'create',route,r.rows[0].id);res.status(201).json(r.rows[0])}catch(e){res.status(400).json({error:'invalid_data'})}}); }
app.get('/api/products/public/:restaurantId',async(req,res)=>{try{const r=await q('SELECT id,category,name,description,price,emoji,image_url FROM products WHERE restaurant_id=$1 AND active=true ORDER BY category,name',[req.params.restaurantId]);res.json(r.rows)}catch{res.status(503).json({error:'database_unavailable'})}});
