// Recipes and ingredients (owner/manager only). Quantities are positive and units are explicit.
const STOCK_UNITS = new Set(['g','kg','ml','l','un','unit']);
const unitInfo = {g:['mass',1],kg:['mass',1000],ml:['volume',1],l:['volume',1000],un:['count',1],unit:['count',1]};
function validUnit(v){const u=cleanText(v,12).toLowerCase();return STOCK_UNITS.has(u)?u:null;}
function positive(v){return Number.isFinite(Number(v))&&Number(v)>0&&Number(v)<=1000000?Number(v):null;}
function nonnegative(v){return Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100000000?Number(v):null;}
function compatible(a,b){return unitInfo[a]&&unitInfo[b]&&unitInfo[a][0]===unitInfo[b][0];}
function convertQty(value,from,to){if(!compatible(from,to))return null;return value*unitInfo[from][1]/unitInfo[to][1];}
