async function saveRecipe(req,res){const b=req.body||{},productId=cleanText(b.productId??b.product_id,100),yieldQuantity=positive(b.yieldQuantity??b.yield_quantity??1),yieldUnit=validUnit(b.yieldUnit??b.yield_unit??'un'),items=Array.isArray(b.ingredients)?b.ingredients:[];if(!productId||yieldQuantity===null||!yieldUnit||items.length>200)return res.status(400).json({error:'invalid_recipe'});const parsed=items.map(x=>({ingredientId:cleanText(x.ingredientId??x.ingredient_id,100),quantity:positive(x.quantity),unit:validUnit(x.unit)}));if(parsed.some(x=>!x.ingredientId||x.quantity===null||!x.unit||parsed.filter(y=>y.ingredientId===x.ingredientId).length>1))return res.status(400).json({error:'invalid_recipe_ingredient'});const c=await pool.connect();try{await ensureSchema();await c.query('BEGIN');const product=await c.query('SELECT id FROM products WHERE id=$1 AND restaurant_id=$2',[productId,req.user.rid]);if(!product.rowCount){await c.query('ROLLBACK');return res.status(400).json({error:'product_not_found'})}const ir=await c.query('SELECT id,unit FROM ingredients WHERE restaurant_id=$1 AND id=ANY($2::text[])',[req.user.rid,parsed.map(x=>x.ingredientId)]);const by=new Map(ir.rows.map(x=>[x.id,x]));if(ir.rowCount!==parsed.length||parsed.some(x=>!compatible(x.unit,by.get(x.ingredientId).unit))){await c.query('ROLLBACK');return res.status(400).json({error:'incompatible_unit'})}const old=await c.query('SELECT id FROM recipes WHERE product_id=$1 AND restaurant_id=$2',[productId,req.user.rid]);let recipeId=old.rows[0]?.id;if(recipeId)await c.query('UPDATE recipes SET yield_quantity=$1,yield_unit=$2,notes=$3,active=true,updated_at=now() WHERE id=$4',[yieldQuantity,yieldUnit,cleanText(b.notes,500)||null,recipeId]);else {recipeId=id();await c.query('INSERT INTO recipes(id,restaurant_id,product_id,yield_quantity,yield_unit,notes) VALUES($1,$2,$3,$4,$5,$6)',[recipeId,req.user.rid,productId,yieldQuantity,yieldUnit,cleanText(b.notes,500)||null]);}await c.query('DELETE FROM recipe_ingredients WHERE recipe_id=$1',[recipeId]);for(const x of parsed)await c.query('INSERT INTO recipe_ingredients(id,recipe_id,ingredient_id,quantity,unit) VALUES($1,$2,$3,$4,$5)',[id(),recipeId,x.ingredientId,x.quantity,x.unit]);await c.query('COMMIT');await audit(req,old.rowCount?'update':'create','recipe',recipeId);const out=await q('SELECT r.*,p.name product_name,COALESCE(json_agg(json_build_object(\'ingredientId\',ri.ingredient_id,\'quantity\',ri.quantity,\'unit\',ri.unit)) FILTER (WHERE ri.id IS NOT NULL),\'[]\') ingredients FROM recipes r JOIN products p ON p.id=r.product_id LEFT JOIN recipe_ingredients ri ON ri.recipe_id=r.id WHERE r.id=$1 GROUP BY r.id,p.name',[recipeId]);res.status(old.rowCount?200:201).json(out.rows[0])}catch(e){await c.query('ROLLBACK').catch(()=>{});res.status(400).json({error:'invalid_recipe'})}finally{c.release()}}
